:root{
  --c-bg:#f7f9fd;
  --c-surface:#ffffff;
  --c-fill:#f2f4f8;
  --c-fill-strong:#e6e8ec;
  --c-line:#e6e8ec;
  --c-text:#191c1f;
  --c-text-2:#424655;
  --c-text-3:#737686;
  --c-brand:#075ed1;
  --c-brand-soft:#edf1ff;
  --c-warn:#ef7f13;
  --c-warn-soft:#fff0dc;
  --c-critical:#c31d24;
  --c-critical-soft:#ffe9e8;
  --c-orange:#fe9c2d;
  --r-card:12px;
  --r-ctl:8px;
  --shadow-card:0 1px 2px #0000000d;
}

page{
  min-height:100vh;
  background:var(--c-bg);
  color:var(--c-text);
  font-family:'Noto Sans SC:Medium','Noto Sans SC',-apple-system,BlinkMacSystemFont,'PingFang SC','Microsoft YaHei',sans-serif;
  font-size:18px;
  font-weight:400;
  line-height:1.5;
  box-sizing:border-box;
}
view,text,image,input,textarea,scroll-view,label{box-sizing:border-box;margin:0;padding:0;border:0 solid}
image{display:block;max-width:100%}
input,textarea{font:inherit;color:inherit;background:transparent;outline:none;border:0 solid}

/* 灞忓箷瀹瑰櫒锛氶〉澶?72px + 搴曢儴鎿嶄綔鏍?72px */
.screen{min-height:100vh;min-height:100dvh;background:var(--c-bg);padding:calc(72px + var(--status-bar-height,0px)) 0 calc(72px + env(safe-area-inset-bottom));position:relative;margin:auto;max-width:720px;box-sizing:border-box}
.form-screen{padding-bottom:calc(72px + env(safe-area-inset-bottom))}

/* 鍥哄畾椤靛ご锛氬綊妗ｆ埅鍥鹃〉澶撮珮 72px */
.app-header{position:fixed;z-index:20;top:var(--status-bar-height,0px);left:0;right:0;margin:0 auto;max-width:720px;height:72px;display:flex;align-items:center;justify-content:center;background:rgba(255,255,255,.96);backdrop-filter:blur(24px);-webkit-backdrop-filter:blur(24px);box-shadow:0 1px 8px #0000000a}
.app-header-title{font-size:19px;font-weight:500;line-height:25px}
.app-back{position:absolute;left:14px;top:0;height:72px;display:flex;align-items:center}
.app-back-glyph{font-family:sans-serif;font-weight:400;font-size:32px;line-height:1}

/* ===== 宸ヤ綔鍙?===== */
.workspace{display:flex;gap:12px;padding:10px 16px}
.workspace-aside{width:80px;display:flex;flex-direction:column;gap:8px;flex:none}
.side-tab{height:76px;text-align:center;border-radius:12px;background:var(--c-fill);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;font-size:14px;position:relative}
.side-tab-image{width:20px;height:20px}
.side-tab.active{background:var(--c-brand-soft);color:#004fd0}
.side-tab.active::before{content:'';position:absolute;left:0;top:8px;bottom:8px;width:4px;border-radius:0 9px 9px 0;background:#004fd0}
.apps{flex:1;min-width:0}
.section-title{height:38px;padding:0 12px;background:var(--c-surface);border-radius:var(--r-ctl);display:flex;align-items:center;justify-content:space-between;box-shadow:var(--shadow-card);font-size:16px;margin-bottom:8px}
.section-title-text{font-weight:700}
.section-title-count{font-size:13px;color:var(--c-text-2);background:var(--c-fill-strong);padding:2px 8px;border-radius:99px}
.app-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
.app-card{height:116px;text-align:center;background:var(--c-surface);border-radius:var(--r-card);box-shadow:var(--shadow-card);display:flex;flex-direction:column;align-items:center;justify-content:center}
.icon-well{width:48px;text-align:center;height:48px;border-radius:16px;display:grid;place-items:center;margin-bottom:6px;background:#eff6ffcc}
