import { computed } from 'vue'

/** 鐘舵€佹爮楂樺害锛欻5 妗岄潰涓庣Щ鍔ㄦ祻瑙堝櫒涓?0锛屽井淇″皬绋嬪簭涓哄垬娴?鑳跺泭鍖哄煙楂樺害 */
export function useStatusBar() {
  const height = (() => {
