await p.waitForTimeout(2000)
const data = await p.evaluate(()=>{
  const pick = sel => { const el=document.querySelector(sel); if(!el) return null; const r=el.getBoundingClientRect(); const cs=getComputedStyle(el); return {rect:{x:Math.round(r.x),y:Math.round(r.y),w:Math.round(r.width),h:Math.round(r.height)}, bg:cs.backgroundColor, color:cs.color, fs:cs.fontSize, fw:cs.fontWeight, br:cs.borderRadius, pad:cs.padding, border:cs.border, boxShadow:cs.boxShadow} }
  // find card container
  const all = {}
  const sels = ['body','#root','.login','.login-page','.login-card','.header','.title','.logo','.brand','.tabs','.tab-bar','.field','.field-label','.field-input','input','.captcha','.primary-button','.agreement','.checkbox']
  for(const s of sels){ const v=pick(s); if(v) all[s]=v }
  // dump top-level structure of login page
  const root=document.querySelector('#root')
  const walk=(el,d)=>{ if(d>4) return ''; const cs=getComputedStyle(el); const r=el.getBoundingClientRect(); let s='  '.repeat(d)+`<${el.tagName.toLowerCase()} class="${el.className}"> x=${Math.round(r.x)} y=${Math.round(r.y)} w=${Math.round(r.width)} h=${Math.round(r.height)} bg=${cs.backgroundColor} fs=${cs.fontSize} fw=${cs.fontWeight} color=${cs.color}\n`; for(const c of el.children) s+=walk(c,d+1); return s }
  return { sels: all, tree: root?walk(root,0):'no root' }
})
console.log(JSON.stringify(data.sels,null,1))
console.log('=== TREE ===')
