import { test, expect } from '@playwright/test'
import { mkdirSync } from 'node:fs'

/**
 * 登录页视觉/结构 E2E（目标：与设计图 100% 对齐）
 * 站点：本地 nginx 部署的 worktree dist（默认 http://127.0.0.1:8095）。
 * 断言：字段顺序与标签、图标、获取验证码、图形验证码、密码登录链接、协议勾选、登录按钮，
 *       以及关键几何尺寸（卡片宽度/内边距/圆角、输入行高、主按钮高度）符合设计规范。
 * 同时在 test-results 落盘截图，供人工比对。
 */

const SHOT_DIR = 'artifacts/visual'

test.beforeAll(() => { mkdirSync(SHOT_DIR, { recursive: true }) })

test('登录页：字段与布局符合设计图', async ({ page }) => {
  await page.goto('/', { waitUntil: 'domcontentloaded' })
  await page.waitForTimeout(1500)

  // 顶部标题
  await expect(page.getByText('登录', { exact: true }).first()).toBeVisible()
  // 品牌名
  await expect(page.getByText('苏州市服务监管平台').first()).toBeVisible()

  // 四个字段标签，按设计图顺序
  const labels = page.locator('.login-field-label')
  await expect(labels.nth(0)).toContainText('手机号码')
  await expect(labels.nth(1)).toContainText('身份证号后四位')
  await expect(labels.nth(2)).toContainText('验证码')
  await expect(labels.nth(3)).toContainText('图形验证码')
  await expect(labels).toHaveCount(4)

  // 获取验证码 + 图形验证码占位 + 密码登录 + 协议 + 登录按钮
  await expect(page.getByText('获取验证码').first()).toBeVisible()
  await expect(page.locator('.login-captcha-img')).toBeVisible()
  await expect(page.getByText('密码登录').first()).toBeVisible()
  await expect(page.getByText('请勾选同意用户协议和隐私协议').first()).toBeVisible()
  const submit = page.locator('.login-submit')
  await expect(submit).toBeVisible()
  await expect(submit).toContainText('登录')

  // 每个字段输入壳带图标
  await expect(page.locator('.login-input-icon')).toHaveCount(4)

  // 几何尺寸断言（设计规范）
  const card = page.locator('.login-card')
  const cardBox = await card.boundingBox()
  expect(cardBox).not.toBeNull()
  // 卡片左右各 16px 外边距（390 视口 → 宽 358）
  expect(Math.round(cardBox!.x)).toBe(16)
  expect(Math.round(cardBox!.width)).toBe(358)
  const cardStyle = await card.evaluate(el => {
    const cs = getComputedStyle(el)
    return { br: cs.borderRadius, pad: cs.padding }
  })
  expect(cardStyle.br).toBe('12px')
  expect(cardStyle.pad).toBe('16px')

  // 输入壳行高 48
  const shellBox = await page.locator('.login-input-shell').first().boundingBox()
  expect(Math.round(shellBox!.height)).toBe(48)

  // 主按钮高 48、圆角 8、品牌蓝底
  const btnBox = await submit.boundingBox()
  expect(Math.round(btnBox!.height)).toBe(48)
