import { chromium } from '@playwright/test'
import { mkdirSync } from 'node:fs'
const browser = await chromium.launch({ executablePath: process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE })
mkdirSync('artifacts/leadverify', { recursive: true })
const base = 'http://127.0.0.1:8095'
const routes = {
  'history': '/#/pages/history/index',
  'detail': '/#/pages/detail/index',
  'project-records': '/#/pages/project-check/records/index',
  'rescue': '/#/pages/rescue/index',
}
const p = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 })
for (const [name, r] of Object.entries(routes)) {
  await p.goto(base + r, { waitUntil: 'domcontentloaded' })
  await p.waitForTimeout(1500)
  await p.screenshot({ path: `artifacts/leadverify/${name}.png`, animations: 'disabled', timeout: 60000 })
  // measure header bottom and first content top
  const m = await p.evaluate(()=>{
    const h = document.querySelector('.app-header')
    const hb = h ? Math.round(h.getBoundingClientRect().bottom) : null
    // first visible child in a screen
    return { headerBottom: hb }
  })
  console.log(name, JSON.stringify(m))
}
await browser.close()

