import { chromium } from '@playwright/test'
import { mkdirSync } from 'node:fs'
const browser = await chromium.launch({ executablePath: process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE })
mkdirSync('artifacts/refdata', { recursive: true })
const p = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 })
await p.goto('http://localhost:8443/', { waitUntil: 'domcontentloaded' }); await p.waitForTimeout(2000)
const inputs = p.locator('input'); const n = await inputs.count()
for(let i=0;i<n;i++){ const t=await inputs.nth(i).getAttribute('type'); if(t==='checkbox') await inputs.nth(i).check(); else await inputs.nth(i).fill(i===0?'admin':'x123456') }
await p.getByRole('button',{name:'登录',exact:true}).click(); await p.waitForTimeout(1500)
await p.getByText('物业手持端',{exact:false}).first().click(); await p.waitForTimeout(1500)
// click 数智 bottom nav
await p.getByText('数智',{exact:true}).first().click(); await p.waitForTimeout(1500)
// full text
const txt = await p.evaluate(()=>document.body.innerText)
console.log('=== DATA TEXT ===\n'+txt)
// dump structure: sections, their classes, first ~ children
const struct = await p.evaluate(()=>{
  const main = document.querySelector('.page, main, .app-viewport') || document.body
  const walk=(el,d)=>{ if(d>5) return ''; const cs=getComputedStyle(el); const r=el.getBoundingClientRect(); let s='  '.repeat(d)+`<${el.tagName.toLowerCase()} class="${(el.className||'').toString().slice(0,40)}"> y=${Math.round(r.y)} h=${Math.round(r.height)} bg=${cs.backgroundColor} br=${cs.borderRadius}\n`; if(d<4) for(const c of el.children) s+=walk(c,d+1); return s }
  return walk(main,0)
})
console.log('=== STRUCT ===\n'+struct.slice(0,6000))
await p.screenshot({ path:'artifacts/refdata/top.png', fullPage:false, animations:'disabled', timeout:60000 })
// scroll to bottom
await p.evaluate(()=>{ const sc=document.querySelector('.app-viewport, .page, main')||document.scrollingElement; window.scrollTo(0, document.body.scrollHeight); })
await p.waitForTimeout(800)
await p.screenshot({ path:'artifacts/refdata/bottom.png', fullPage:false, animations:'disabled', timeout:60000 })
await browser.close()

import { chromium } from '@playwright/test'
import { mkdirSync } from 'node:fs'
const browser = await chromium.launch({ executablePath: process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE })
mkdirSync('artifacts/refdata', { recursive: true })
const p = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 })
// block external font faces to avoid screenshot hang
await p.route('**/font/**', r=>r.abort()).catch(()=>{})
await p.route('**/*.woff2*', r=>r.abort()).catch(()=>{})
await p.goto('http://localhost:8443/', { waitUntil: 'domcontentloaded' }); await p.waitForTimeout(2000)
const inputs = p.locator('input'); const n = await inputs.count()
for(let i=0;i<n;i++){ const t=await inputs.nth(i).getAttribute('type'); if(t==='checkbox') await inputs.nth(i).check(); else await inputs.nth(i).fill(i===0?'admin':'x123456') }
await p.getByRole('button',{name:'登录',exact:true}).click(); await p.waitForTimeout(1500)
await p.getByText('物业手持端',{exact:false}).first().click(); await p.waitForTimeout(1500)
await p.getByText('数智',{exact:true}).first().click(); await p.waitForTimeout(1500)
const shot = async(name)=>{ try{ await p.screenshot({ path:`artifacts/refdata/${name}.png`, animations:'disabled', timeout:20000 }) }catch(e){ console.log('shot fail',name,e.message) } }
await shot('top')
const H = await p.evaluate(()=>document.body.scrollHeight)
console.log('scrollHeight', H)
// capture in three scroll positions
for(const [i,y] of [[1,700],[2,1400],[3,2100]]){
  await p.evaluate(yy=>window.scrollTo(0,yy), y); await p.waitForTimeout(600); await shot('scroll'+i)
}
// structure sections
const struct = await p.evaluate(()=>{
  const out=[]
  document.querySelectorAll('section, .section, .card, [class*="card"], [class*="section"], [class*="metric"]').forEach(el=>{
    const r=el.getBoundingClientRect(); const cs=getComputedStyle(el)
    if(r.height>0) out.push({cls:(el.className||'').toString().slice(0,50), y:Math.round(r.y), h:Math.round(r.height), t:(el.innerText||'').trim().slice(0,25)})
  })
  return out.slice(0,60)
})
console.log(JSON.stringify(struct,null,0).slice(0,4000))
await browser.close()

import { chromium } from '@playwright/test'
import { mkdirSync } from 'node:fs'
const browser = await chromium.launch({ executablePath: process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE })
mkdirSync('artifacts/final', { recursive: true })
const p = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 })
const shot = async (name) => { try { await p.screenshot({ path: `artifacts/final/${name}.png`, animations:'disabled', timeout:30000 }) } catch(e){ console.log('shotfail',name) } }
// login
await p.goto('http://127.0.0.1:8095/', { waitUntil:'domcontentloaded' }); await p.waitForTimeout(1200); await shot('login')
const routes = {
  home: '/#/pages/home/index',
  workbench: '/#/pages/workbench/index',
  housing: '/#/pages/housing/index',
  data: '/#/pages/data/index',
  systems: '/#/pages/systems/index',
}
for (const [k,r] of Object.entries(routes)){ await p.goto('http://127.0.0.1:8095'+r, { waitUntil:'domcontentloaded' }); await p.waitForTimeout(1200); await shot(k) }
console.log('done')
await browser.close()
